# Soufflé input-relation -> client IR CSV basename (the file staged as that relation's facts).
# One relation per line: <relation><TAB><csv-basename>  (no extension handling here).
# All 19 relations of the frozen Python fact schema. A relation whose CSV is absent from a
# given IR directory is simply not staged (run-souffle.sh skips it), so a small project that
# has no decorators or no parse gaps still solves.
py_binding	all-python-bindings
py_block	all-python-blocks
py_call_site	all-python-call-sites
py_comment	all-python-comments
py_decorator	all-python-decorators
py_decorator_argument	all-python-decorator-arguments
py_expression	all-python-expressions
py_field	all-python-fields
py_field_position	all-python-field-positions
py_import	all-python-imports
py_method	all-python-methods
py_method_parameter	all-python-method-parameters
py_module	all-python-modules
py_parse_gap	all-python-parse-gaps
py_scope	all-python-scopes
py_type	all-python-types
py_type_base	all-python-type-bases
py_type_parameter	all-python-type-parameters
py_type_reference	all-python-type-references
